<script setup lang="ts">
import{computed,onMounted,ref,watch}from"vue";import{useRoute,useRouter}from"vue-router";import BaseEmptyState from"@/components/base/BaseEmptyState.vue";import BasePageHeader from"@/components/base/BasePageHeader.vue";import type{TitleRecord}from"@/types/records";import{titleRepository}from"@/domain/repositories";import{pb}from"@/infrastructure/pocketbase/client";
const route=useRoute(),router=useRouter(),items=ref<TitleRecord[]>([]),total=ref(0),loading=ref(false),error=ref(""),query=ref(String(route.query.pesquisa||""));const safeQuery=computed(()=>query.value.replaceAll('"','\\"'));const poster=(i:TitleRecord)=>i.poster?pb.files.getURL(i,i.poster,{thumb:"300x450"}):i.poster_url||"";
async function load(){loading.value=true;error.value="";try{const filter=`apagado = false${safeQuery.value?` && titulo ~ "${safeQuery.value}"`:""}`;const page=await titleRepository.list({perPage:36,filter,sort:"-updated"});items.value=page.items;total.value=page.totalItems}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}function search(){void router.replace({name:"catalog",query:query.value?{pesquisa:query.value}:{}})}watch(()=>route.query.pesquisa,()=>{query.value=String(route.query.pesquisa||"");void load()});onMounted(()=>void load());
</script><template><BasePageHeader eyebrow="Biblioteca digital" title="Catálogo" :description="`${total} títulos encontrados`"><template #actions><RouterLink class="button button-secondary" to="/lixeira">Lixeira</RouterLink><RouterLink class="button button-primary" to="/catalogo/novo">＋ Novo título</RouterLink></template></BasePageHeader><form class="filter-bar" @submit.prevent="search"><input v-model="query" name="pesquisa" placeholder="Pesquisar no catálogo…"><button class="button button-secondary">Pesquisar</button></form><section v-if="loading" class="page-loading"><span class="loader"/></section><BaseEmptyState v-else-if="error" icon="!" title="Não foi possível carregar o catálogo" :description="error"><button class="button button-secondary" @click="load">Voltar a tentar</button></BaseEmptyState><div v-else-if="items.length" class="media-grid"><RouterLink v-for="item in items" :key="item.id" class="media-card" :to="`/catalogo/${item.id}`"><div class="poster-placeholder"><img v-if="poster(item)" :src="poster(item)" :alt="`Poster de ${item.titulo}`" loading="lazy"><span v-else>▶</span></div><div class="media-info"><span>{{item.ano||'Ano desconhecido'}}</span><strong>{{item.titulo}}</strong><small>{{item.tagline||'Sem descrição'}}</small></div></RouterLink></div><BaseEmptyState v-else icon="◫" title="Nenhum título encontrado" description="Adiciona o primeiro conteúdo ao catálogo."/></template>
